const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET env is not set');
const item = $input.first();
const headers = item.json.headers ?? {};
const signature = headers['x-webhook-signature'] ?? headers['X-Webhook-Signature'];
const idempotencyKey = headers['x-idempotency-key'] ?? headers['X-Idempotency-Key'];
if (!signature || !idempotencyKey) throw new Error('Missing webhook signature or idempotency key');
const rawBody = JSON.stringify(item.json.body ?? item.json);
const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
if (signature !== expected) throw new Error('Invalid webhook signature');
const payload = item.json.body?.payload ?? item.json.payload ?? {};
if (!payload.appointmentId || !payload.businessId || !payload.action) throw new Error('Invalid appointment payload');
return [{ json: { ...payload, _idempotencyKey: idempotencyKey } }];

const data = $getWorkflowStaticData('global');
data.seen = data.seen || {};
const now = Date.now();
for (const k of Object.keys(data.seen)) { if (data.seen[k] < now - 86400000) delete data.seen[k]; }
const item = $input.first().json;
if (data.seen[item._idempotencyKey]) { return [{ json: { ...item, _duplicate: true } }]; }
data.seen[item._idempotencyKey] = now;
const labels = { created: 'نوبت جدید', rescheduled: 'جابه‌جایی نوبت', cancelled: 'لغو نوبت' };
const text = `${labels[item.action] ?? item.action}\nزمان: ${item.scheduledAt ?? '—'}\nشناسه: ${item.appointmentId}`;
return [{ json: { ...item, _duplicate: false, _message: text } }];
